        ('От определения к функции', p('В функции y = ⁿ√x каждому допустимому x соответствует одно значение корня. Показатель n фиксирован и является натуральным числом не меньше 2. Меняется аргумент x, а не показатель n.') + rule('D(f) — область определения, то есть допустимые x. E(f) — область значений, то есть все получающиеся y. Их нельзя смешивать с видимым фрагментом графика.')),
        ('Чётный корень: y = ²ᵏ√x', table(['Свойство','Описание'], [('D(f) и E(f)','[0; +∞) и [0; +∞)'),('Нуль и знак','f(0) = 0; при x &gt; 0 значение положительно'),('Монотонность','Возрастает на [0; +∞)'),('Чётность','Ни чётная, ни нечётная: область определения не симметрична относительно 0'),('Экстремальные значения','Наименьшее 0 при x = 0; наибольшего нет')]) + p('Для построения четвёртого корня удобно задать y, затем вычислить x = y⁴: получаем точки (0; 0), (1; 1), (16; 2). График не имеет отрицательной ветви.') + graph('Чётные корни: квадратный и четвёртый', [('y = √x','#2563eb',root_samples(2,0,4)),('y = ⁴√x','#7c3aed',root_samples(4,0,2))], (0,16,0,4), [0,4,8,12,16], [0,1,2,3,4], 'Оба графика начинаются в (0; 0) и проходят через (1; 1). Масштаб по x: 4 единицы на клетку, по y: 1 единица. При x = 16 значения равны 4 и 2.')),
        ('Нечётный корень: y = ²ᵏ⁺¹√x', table(['Свойство','Описание'], [('D(f) и E(f)','ℝ и ℝ'),('Нуль и знак','Нуль при x = 0; знак y совпадает со знаком x'),('Монотонность','Возрастает на всей ℝ'),('Чётность','Нечётная: f(−x) = −f(x)'),('Симметрия и ограничения','Симметрия относительно начала координат; наибольшего и наименьшего значений нет')]) + graph('График кубического корня', [('y = ∛x','#2563eb',root_samples(3,-2,2))], (-8,8,-2,2), [-8,-4,0,4,8], [-2,-1,0,1,2], 'Точные точки: (−8; −2), (−1; −1), (0; 0), (1; 1), (8; 2). Масштабы по осям различаются: по x — 4, по y — 1 единица на клетку.') + note('Функция возрастает и при отрицательных x. Например, −27 &lt; −8, поэтому ∛(−27) = −3 &lt; −2 = ∛(−8).')),
        ('Сравнение корней и связь со степенью', rule('Для одинакового показателя n: a &lt; b ⇒ ⁿ√a &lt; ⁿ√b, если оба корня определены.') + example('Пример 1. Сравнение', '⁴√70 &lt; 3, потому что 70 &lt; 3⁴ = 81. А ⁵√(−40) &lt; −2, поскольку −40 &lt; (−2)⁵ = −32.') + p('Графики y = xⁿ и y = ⁿ√x связаны обменом координат. Для нечётного n функция xⁿ обратима на ℝ. Для чётного n сначала ограничивают её на x ≥ 0: на всей ℝ одному положительному значению xⁿ соответствуют два противоположных x.')),
        ('Область определения сложного выражения', example('Пример 2. Сумма корней', 'Для y = √(x − 1) + ⁴√(5 − x) нужны одновременно x − 1 ≥ 0 и 5 − x ≥ 0. Пересечение даёт <strong>D(f) = [1; 5]</strong>.') + example('Пример 3. Квадратный трёхчлен', 'Для y = ⁴√(9 − x²) нужно x² ≤ 9. Значит, <strong>D(f) = [−3; 3]</strong>. Подкоренное выражение принимает значения от 0 до 9, поэтому <strong>E(f) = [0; √3]</strong>, так как ⁴√9 = √3.') + example('Пример 4. Нечётный корень в знаменателе', 'Для y = 1 / ∛(x − 4) исключаем только x = 4: знаменатель не должен равняться нулю. Область определения — (−∞; 4) ∪ (4; +∞).')),
        ('Перенос графика', rule('y = ⁿ√(x − a) + b: график y = ⁿ√x переносится на a по горизонтали и на b по вертикали. При a &gt; 0 — вправо, при b &gt; 0 — вверх. Точка (0; 0) переходит в (a; b).') + example('Пример 5. Чётный корень со сдвигом', 'y = √(x − 2) + 1. Сдвигаем график вправо на 2 и вверх на 1. Точки (0; 0), (1; 1), (4; 2) переходят в <strong>(2; 1), (3; 2), (6; 3)</strong>. D = [2; +∞), E = [1; +∞).') + graph('Перенос y = √x в y = √(x − 2) + 1', [('y = √x','#2563eb',root_samples(2,0,2.8)),('y = √(x − 2) + 1','#7c3aed',[(x+2,y+1) for x,y in root_samples(2,0,2.4)])], (0,8,0,4), [0,2,4,6,8], [0,1,2,3,4], 'Начало фиолетового графика находится в (2; 1). График продолжается вправо за пределы рисунка. По x — 2 единицы на клетку, по y — 1.') + example('Пример 6. Нечётный корень со сдвигом', 'y = ∛(x + 3) − 2 — перенос влево на 3 и вниз на 2. D = E = ℝ; функция возрастает на ℝ, но после такого переноса уже не является нечётной.')),
        ('Пересечения и простые неравенства', example('Пример 7. Пересечение с прямой', 'Для y = √x и y = x − 2 решаем √x = x − 2. Нужно x ≥ 2. Тогда x = (x − 2)² ⇒ x² − 5x + 4 = 0 ⇒ x = 1 или x = 4. Подходит только 4. <strong>Точка пересечения (4; 2)</strong>.') + example('Пример 8. Прочитать неравенство', '⁴√(x + 1) ≤ 2. Сначала x + 1 ≥ 0, затем благодаря возрастанию корня x + 1 ≤ 16. Получаем <strong>−1 ≤ x ≤ 15</strong>.') + note('Для определения числа пересечений рисунок помогает выдвинуть предположение. Точные координаты находят из уравнения и проверяют в исходных формулах.')),
